// The golden test of DESIGN.md §3.2: the C++ policy runner against v2's NumPy executor (r1mc2/policy.py NumpyOnnx)
// on the committed observation set tests/assets/policy_golden/golden_1000.bin (500 sim observations - 250 from v2's
// full stack running on r1sim through the adapter, 250 from v2's WalkPolicy.observe balancing the robot in r1sim
// directly - and 500 in-range random ones; expected actions = v2's executor in float64; generated by
// tools/policy_golden.py). The full 10,000-vector run is tests/unit/test_policy_golden.py (needs R1_V2_DIR).
#include <gtest/gtest.h>

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>

#include "r1rt/policy_mlp.hpp"

namespace {

constexpr double kTol = 1e-5;  // DESIGN.md §3.2

std::uint32_t rd_u32(const unsigned char* p) {
  return std::uint32_t{p[0]} | (std::uint32_t{p[1]} << 8) | (std::uint32_t{p[2]} << 16) | (std::uint32_t{p[3]} << 24);
}

struct Golden {
  std::uint32_t n = 0, n_sim = 0;
  std::vector<double> obs, act;
};

bool read_golden(const char* path, Golden& g) {
  std::ifstream f(path, std::ios::binary);
  unsigned char h[32];
  if (!f.read(reinterpret_cast<char*>(h), 32)) return false;
  if (std::memcmp(h, "R1G1", 4) != 0 || rd_u32(h + 4) != 1 || rd_u32(h + 12) != r1rt::PolicyMlp::kObs ||
      rd_u32(h + 16) != r1rt::PolicyMlp::kAct)
    return false;
  g.n = rd_u32(h + 8);
  g.n_sim = rd_u32(h + 20);
  g.obs.resize(std::size_t{g.n} * r1rt::PolicyMlp::kObs);
  g.act.resize(std::size_t{g.n} * r1rt::PolicyMlp::kAct);
  return static_cast<bool>(f.read(reinterpret_cast<char*>(g.obs.data()),
                                  static_cast<std::streamsize>(g.obs.size() * sizeof(double)))) &&
         static_cast<bool>(f.read(reinterpret_cast<char*>(g.act.data()),
                                  static_cast<std::streamsize>(g.act.size() * sizeof(double))));
}

}  // namespace

TEST(PolicyGolden, MatchesV2NumpyExecutorOnTheCommittedSet) {
  {
    std::ifstream w(R1RT_POLICY_WEIGHTS, std::ios::binary);
    if (!w.good()) GTEST_SKIP() << "no converted weights at " << R1RT_POLICY_WEIGHTS;
  }
  Golden g;
  ASSERT_TRUE(read_golden(R1RT_POLICY_GOLDEN, g)) << "cannot read " << R1RT_POLICY_GOLDEN;
  ASSERT_EQ(g.n, 1000u);
  ASSERT_EQ(g.n_sim, 500u);
  r1rt::PolicyMlp mlp;
  char err[256] = {0};
  ASSERT_TRUE(mlp.load(R1RT_POLICY_WEIGHTS, err, sizeof err)) << err;

  double max_err = 0.0, max_err_sim = 0.0, max_act = 0.0;
  std::uint32_t worst = 0;
  double out[r1rt::PolicyMlp::kAct];
  for (std::uint32_t i = 0; i < g.n; ++i) {
    mlp.run(&g.obs[std::size_t{i} * r1rt::PolicyMlp::kObs], out);
    for (int k = 0; k < r1rt::PolicyMlp::kAct; ++k) {
      const double want = g.act[std::size_t{i} * r1rt::PolicyMlp::kAct + static_cast<std::size_t>(k)];
      const double e = std::fabs(out[k] - want);
      ASSERT_TRUE(std::isfinite(out[k])) << "row " << i << " action " << k;
      if (e > max_err) {
        max_err = e;
        worst = i;
      }
      if (i < g.n_sim && e > max_err_sim) max_err_sim = e;
      if (std::fabs(want) > max_act) max_act = std::fabs(want);
    }
  }
  std::printf("[ golden ] %u vectors (%u from v2's observation code in the sim): max |C++ - v2| = %.3e "
              "(sim rows %.3e; worst row %u; largest |action| %.2f); tolerance %.0e\n",
              g.n, g.n_sim, max_err, max_err_sim, worst, max_act, kTol);
  RecordProperty("max_abs_err", std::to_string(max_err));
  EXPECT_LE(max_err, kTol);
}
